import{d as e,i as t}from"./index-BVdLvPw-.js";import{t as n}from"./BlogPost-BCN0DswP.js";var r=t();function i(){return(0,r.jsxs)(n,{path:`/blog-choose-it-support`,children:[(0,r.jsx)(`p`,{children:`The right IT provider prevents problems instead of just fixing them. Use these questions when comparing providers.`}),(0,r.jsx)(`p`,{children:`Most providers sound similar on a website. The differences show up in the detail: how they handle a problem at 7am on a Monday, what they document, and what happens if you decide to leave. Ask every shortlisted provider the same questions and compare the answers side by side.`}),(0,r.jsx)(`h2`,{children:`Ten questions`}),(0,r.jsxs)(`ol`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`What are your average response and resolution times, and are they reported?`}),` Response time is how quickly someone acknowledges the issue. Resolution time is how long it takes to fix. Ask for a sample monthly report so you can see what you would actually receive.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Is support available after hours and on weekends?`}),` Ask whether after-hours work is included or charged separately, and how you reach someone urgently. This matters if you trade on weekends or have staff in other time zones.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`How do we raise and track tickets?`}),` Email, phone and a portal are common. You want every request logged with a reference number so nothing relies on someone remembering a phone call.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`What security controls do you put in place as standard?`}),` Look for multi-factor authentication, automatic patching, endpoint protection, email filtering and limited admin rights. A provider who refers to the ASD `,(0,r.jsx)(e,{to:`/blog-essential-eight-guide`,children:`Essential Eight`}),` is working from a recognised baseline.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`How do you back up our data, and how often do you test restores?`}),` Ask what is backed up, including Microsoft 365 mailboxes and SharePoint, where copies are stored and when a restore was last tested for a client.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Who is our main contact?`}),` A named person who knows your business saves time. Ask who covers when that person is away.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`How do you document our systems?`}),` Good documentation covers devices, accounts, licences, network settings, vendors and renewal dates. Ask whether you can access it at any time.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`What happens if we leave? Do we keep our accounts and data?`}),` You should own your domain, Microsoft 365 tenancy, admin credentials and documentation. A good provider will describe a clear handover process.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Can you support staff working remotely or overseas?`}),` Remote tools, secure access and device management should be routine, not a special project.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`How do you charge, and what is not included?`}),` Clarify what counts as project work, whether new staff setup is included, and how hardware and software are billed.`]})]}),(0,r.jsx)(`h2`,{children:`How to compare the answers`}),(0,r.jsx)(`p`,{children:`Put the answers in a simple table with one column per provider. Score each question as clear, vague or missing. Vague answers are often more telling than a high price.`}),(0,r.jsxs)(`ol`,{children:[(0,r.jsx)(`li`,{children:`Write down your current pain points first, such as slow fixes, no backups or confusing licensing.`}),(0,r.jsx)(`li`,{children:`Shortlist two or three providers and send them the same list of questions.`}),(0,r.jsx)(`li`,{children:`Ask for a sample report, a sample onboarding plan and a copy of their standard agreement.`}),(0,r.jsx)(`li`,{children:`Speak with the person who would actually support you, not only the salesperson.`}),(0,r.jsx)(`li`,{children:`Read the exit clause and notice period before you compare prices.`})]}),(0,r.jsx)(`h2`,{children:`Pricing models in plain English`}),(0,r.jsxs)(`p`,{children:[`Most managed IT is charged in one of three ways. `,(0,r.jsx)(`b`,{children:`Per user`}),` pricing covers each staff member and all their devices. `,(0,r.jsx)(`b`,{children:`Per device`}),` pricing charges for each computer, server or network device. `,(0,r.jsx)(`b`,{children:`Block hours`}),` or pay-as-you-go suits very small offices but can make it harder to budget and gives the provider less reason to prevent problems.`]}),(0,r.jsxs)(`p`,{children:[`Whichever model you choose, check what sits outside it. Projects such as office moves, server replacements and new system rollouts are usually quoted separately. Software subscriptions such as `,(0,r.jsx)(e,{to:`/microsoft-licensing`,children:`Microsoft licensing`}),` are often billed on their own line.`]}),(0,r.jsx)(`h2`,{children:`Red flags`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Admin passwords only the provider knows.`}),(0,r.jsx)(`li`,{children:`No written scope or reporting.`}),(0,r.jsx)(`li`,{children:`Long lock-in contracts with unclear exit terms.`}),(0,r.jsx)(`li`,{children:`Your Microsoft 365 tenancy or domain registered in the provider's name rather than yours.`}),(0,r.jsx)(`li`,{children:`No mention of backups or security until you ask.`}),(0,r.jsx)(`li`,{children:`Every problem treated as billable project work, with no focus on prevention.`})]}),(0,r.jsx)(`h2`,{children:`Common mistakes when switching`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Choosing on price alone.`}),` A cheaper agreement that excludes most work can cost more over a year.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Not collecting credentials first.`}),` Before giving notice, make sure you hold admin access to your domain, email, firewall and key systems.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Skipping the overlap.`}),` Allow time for the new provider to document everything while the old one is still available to answer questions.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Forgetting the cloud.`}),` Servers, `,(0,r.jsx)(e,{to:`/cloud-maintenance`,children:`cloud services`}),` and phone systems are often managed by different vendors. List them all.`]})]}),(0,r.jsx)(`h2`,{children:`Quick checklist`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Sample report received`}),(0,r.jsx)(`li`,{children:`After-hours arrangements and charges understood`}),(0,r.jsx)(`li`,{children:`Security baseline described in writing`}),(0,r.jsx)(`li`,{children:`Backup and restore testing explained`}),(0,r.jsx)(`li`,{children:`You own all accounts, domains and documentation`}),(0,r.jsx)(`li`,{children:`Exit terms and notice period clear`})]}),(0,r.jsxs)(`p`,{children:[`See how our `,(0,r.jsx)(e,{to:`/support-services`,children:`Support Services`}),` work.`]}),(0,r.jsx)(`h2`,{children:`Frequently asked questions`}),(0,r.jsx)(`h3`,{children:`What is the difference between managed IT and break-fix support?`}),(0,r.jsx)(`p`,{children:`Break-fix support charges when something goes wrong. Managed IT covers ongoing monitoring, patching, security and help desk support for a regular fee, so the focus shifts to preventing problems rather than reacting to them.`}),(0,r.jsx)(`h3`,{children:`How long does it take to switch IT providers?`}),(0,r.jsx)(`p`,{children:`It depends on the size of your environment, the notice period in your current agreement and how well things are documented. Plan for an overlap period so the handover is orderly rather than rushed.`}),(0,r.jsx)(`h3`,{children:`Do we need a local provider if most of our systems are in the cloud?`}),(0,r.jsx)(`p`,{children:`Much support can be delivered remotely, but a provider who can attend on site helps with network faults, new office setups and hardware issues. We are based in Collingwood, Melbourne, and also support clients remotely.`}),(0,r.jsx)(`h3`,{children:`What should a provider do in the first month?`}),(0,r.jsxs)(`p`,{children:[`Expect an audit of devices, accounts and licences, a review of security settings and backups, documentation of your systems and a list of recommended fixes in priority order. If you want to talk it through, `,(0,r.jsx)(e,{to:`/contact`,children:`contact our team`}),`.`]})]})}export{i as default};